public class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // 1. Validate and resolve the object (case-insensitive)
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name cannot be blank.');
        }

        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType objectType = resolveObject(globalDescribe, objectApiName);
        if (objectType == null) {
            throw new SearchException('Object not found: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objDescribe = objectType.getDescribe();
        if (!objDescribe.isAccessible()) {
            throw new SearchException('Insufficient permissions to read object: ' + objDescribe.getName());
        }

        // 2. Validate fields list
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('Fields list cannot be null or empty.');
        }

        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // 3. Resolve and validate requested fields
        List<String> selectFields = new List<String>{'Id'};
        Set<String> selectedSet = new Set<String>{'Id'};

        for (String fieldName : fields) {
            if (String.isBlank(fieldName)) {
                throw new SearchException('Field name in list cannot be blank.');
            }
            Schema.SObjectField sf = resolveField(fieldMap, fieldName);
            if (sf == null) {
                throw new SearchException('Field not found on ' + objDescribe.getName() + ': ' + fieldName);
            }
            String canonicalName = sf.getDescribe().getName();
            if (!sf.getDescribe().isAccessible()) {
                throw new SearchException('Insufficient permissions to read field: ' + canonicalName);
            }
            if (!selectedSet.contains(canonicalName)) {
                selectedSet.add(canonicalName);
                selectFields.add(canonicalName);
            }
        }

        // 4. Resolve and validate filter fields
        Map<String, String> filterKeyToCanonical = new Map<String, String>();
        if (filters != null && !filters.isEmpty()) {
            for (String filterKey : filters.keySet()) {
                if (String.isBlank(filterKey)) {
                    throw new SearchException('Filter field name cannot be blank.');
                }
                Schema.SObjectField sf = resolveField(fieldMap, filterKey);
                if (sf == null) {
                    throw new SearchException('Field not found on ' + objDescribe.getName() + ': ' + filterKey);
                }
                String canonicalName = sf.getDescribe().getName();
                if (!sf.getDescribe().isAccessible()) {
                    throw new SearchException('Insufficient permissions to read field: ' + canonicalName);
                }
                if (!isFilterable(sf.getDescribe().getType())) {
                    throw new SearchException('Field cannot be used in a filter: ' + canonicalName);
                }
                filterKeyToCanonical.put(filterKey, canonicalName);
            }
        }

        // 5. Resolve and validate order-by field
        String canonicalOrderByField = null;
        if (String.isNotBlank(orderByField)) {
            Schema.SObjectField sf = resolveField(fieldMap, orderByField);
            if (sf == null) {
                throw new SearchException('Field not found on ' + objDescribe.getName() + ': ' + orderByField);
            }
            canonicalOrderByField = sf.getDescribe().getName();
            if (!sf.getDescribe().isAccessible()) {
                throw new SearchException('Insufficient permissions to read field: ' + canonicalOrderByField);
            }
            if (!isSortable(sf.getDescribe().getType())) {
                throw new SearchException('Field cannot be used for sorting: ' + canonicalOrderByField);
            }
        }

        // 6. Validate maxRows
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // 7. Build and execute the single SOQL query
        String soql = buildSoql(objDescribe.getName(), selectFields, filters, filterKeyToCanonical, canonicalOrderByField, maxRows);
        return Database.query(soql);
    }

    // ─── Helpers ───────────────────────────────────────────────────────────────

    private static Schema.SObjectType resolveObject(Map<String, Schema.SObjectType> globalDescribe, String apiName) {
        Schema.SObjectType result = globalDescribe.get(apiName);
        if (result != null) {
            return result;
        }
        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(apiName)) {
                return globalDescribe.get(key);
            }
        }
        return null;
    }

    private static Schema.SObjectField resolveField(Map<String, Schema.SObjectField> fieldMap, String apiName) {
        Schema.SObjectField result = fieldMap.get(apiName);
        if (result != null) {
            return result;
        }
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(apiName)) {
                return fieldMap.get(key);
            }
        }
        return null;
    }

    private static Boolean isFilterable(Schema.Type type) {
        if (type == null) {
            return false;
        }
        switch on type {
            when Type.Location, Type.CompoundText, Type.AnyType then {
                return false;
            }
            when else {
                return true;
            }
        }
    }

    private static Boolean isSortable(Schema.Type type) {
        if (type == null) {
            return false;
        }
        switch on type {
            when Type.Location, Type.CompoundText, Type.AnyType then {
                return false;
            }
            when else {
                return true;
            }
        }
    }

    private static String buildSoql(
        String objectName,
        List<String> selectFields,
        Map<String, Object> filters,
        Map<String, String> filterKeyToCanonical,
        String orderByField,
        Integer maxRows
    ) {
        StringBuilder sb = new StringBuilder();
        sb.append('SELECT ');
        sb.append(String.join(selectFields, ', '));
        sb.append(' FROM ');
        sb.append(objectName);

        if (filters != null && !filters.isEmpty()) {
            List<String> conditions = new List<String>();
            for (String key : filters.keySet()) {
                String canonicalField = filterKeyToCanonical.get(key);
                String valueLiteral = formatValue(filters.get(key));
                conditions.add(canonicalField + ' = ' + valueLiteral);
            }
            sb.append(' WHERE ');
            sb.append(String.join(conditions, ' AND '));
        }

        if (String.isNotBlank(orderByField)) {
            sb.append(' ORDER BY ');
            sb.append(orderByField);
            sb.append(' ASC');
        }

        sb.append(' LIMIT ');
        sb.append(String.valueOf(maxRows));

        return sb.toString();
    }

    private static String formatValue(Object value) {
        if (value == null) {
            return 'NULL';
        }
        if (value instanceof String) {
            return "'" + String.escapeSingleQuotes((String) value) + "'";
        }
        if (value instanceof Boolean) {
            return (Boolean) value ? 'true' : 'false';
        }
        if (value instanceof Date) {
            return ((Date) value).format('yyyy-MM-dd');
        }
        if (value instanceof DateTime) {
            return ((DateTime) value).formatGmt('yyyy-MM-dd\'T\'HH:mm:ss') + 'Z';
        }
        if (value instanceof Number) {
            return String.valueOf(value);
        }
        // Fallback: treat as string literal
        return "'" + String.escapeSingleQuotes(String.valueOf(value)) + "'";
    }
}
