public class OrderPayloadParser {

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body is null or blank');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Body is not valid JSON');
        }

        if (parsed == null || !(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Body is not a JSON object');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        // --- number (required) ---
        if (!root.containsKey('number') || root.get('number') == null) {
            throw new PayloadException('Order number is missing');
        }
        Object numObj = root.get('number');
        if (!(numObj instanceof String) || String.isBlank((String) numObj)) {
            throw new PayloadException('Order number is missing or blank');
        }
        String orderNumber = (String) numObj;

        // --- date ---
        Date orderDate = null;
        if (root.containsKey('date') && root.get('date') != null) {
            Object dateObj = root.get('date');
            if (dateObj instanceof String) {
                try {
                    orderDate = Date.valueOf((String) dateObj);
                } catch (Exception e) {
                    orderDate = null;
                }
            }
        }

        // --- currency ---
        String currencyCode = null;
        if (root.containsKey('currency') && root.get('currency') != null) {
            Object curObj = root.get('currency');
            if (curObj instanceof String) {
                currencyCode = (String) curObj;
            }
        }

        // --- customer.email ---
        String customerEmail = null;
        if (root.containsKey('customer') && root.get('customer') != null) {
            Object custObj = root.get('customer');
            if (custObj instanceof Map<String, Object>) {
                Map<String, Object> custMap = (Map<String, Object>) custObj;
                if (custMap.containsKey('email') && custMap.get('email') != null) {
                    Object emailObj = custMap.get('email');
                    if (emailObj instanceof String) {
                        customerEmail = (String) emailObj;
                    }
                }
            }
        }

        // --- lines ---
        List<Line> lines = new List<Line>();
        if (root.containsKey('lines') && root.get('lines') != null) {
            Object linesObj = root.get('lines');
            if (linesObj instanceof List<Object>) {
                List<Object> linesList = (List<Object>) linesObj;
                for (Integer i = 0; i < linesList.size(); i++) {
                    lines.add(parseLine(linesList, i));
                }
            }
        }

        // --- total ---
        Decimal total = 0;
        for (Line line : lines) {
            total += line.lineTotal;
        }

        Order order = new Order();
        order.orderNumber = orderNumber;
        order.orderDate = orderDate;
        order.currencyCode = currencyCode;
        order.customerEmail = customerEmail;
        order.lines = lines;
        order.total = total;

        return order;
    }

    private static Line parseLine(List<Object> linesList, Integer index) {
        Object lineObj = linesList.get(index);
        if (!(lineObj instanceof Map<String, Object>)) {
            throw new PayloadException('Line at index ' + index + ' is not a valid object');
        }
        Map<String, Object> lineMap = (Map<String, Object>) lineObj;

        // sku (required)
        if (!lineMap.containsKey('sku') || lineMap.get('sku') == null) {
            throw new PayloadException('Line at index ' + index + ' is missing sku');
        }
        Object skuObj = lineMap.get('sku');
        if (!(skuObj instanceof String) || String.isBlank((String) skuObj)) {
            throw new PayloadException('Line at index ' + index + ' has missing or blank sku');
        }
        String sku = (String) skuObj;

        // quantity (required, must be positive)
        if (!lineMap.containsKey('quantity') || lineMap.get('quantity') == null) {
            throw new PayloadException('Line at index ' + index + ' is missing quantity');
        }
        Object qtyObj = lineMap.get('quantity');
        Integer quantity;
        if (qtyObj instanceof Double) {
            quantity = (Integer) (Double) qtyObj;
        } else if (qtyObj instanceof Long) {
            quantity = (Integer) (Long) qtyObj;
        } else {
            throw new PayloadException('Line at index ' + index + ' has invalid quantity');
        }
        if (quantity <= 0) {
            throw new PayloadException('Line at index ' + index + ' has non-positive quantity');
        }

        // unitPrice (required, must be non-negative)
        if (!lineMap.containsKey('unitPrice') || lineMap.get('unitPrice') == null) {
            throw new PayloadException('Line at index ' + index + ' is missing unitPrice');
        }
        Object priceObj = lineMap.get('unitPrice');
        Decimal unitPrice;
        if (priceObj instanceof Double) {
            unitPrice = (Decimal) (Double) priceObj;
        } else if (priceObj instanceof Long) {
            unitPrice = (Decimal) (Long) priceObj;
        } else {
            throw new PayloadException('Line at index ' + index + ' has invalid unitPrice');
        }
        if (unitPrice < 0) {
            throw new PayloadException('Line at index ' + index + ' has negative unitPrice');
        }

        // discount (optional, defaults to 0)
        Decimal discount = 0;
        if (lineMap.containsKey('discount') && lineMap.get('discount') != null) {
            Object discObj = lineMap.get('discount');
            if (discObj instanceof Double) {
                discount = (Decimal) (Double) discObj;
            } else if (discObj instanceof Long) {
                discount = (Decimal) (Long) discObj;
            }
        }

        // lineTotal = quantity * unitPrice * (1 - discount), rounded half-up to 2 dp
        Decimal raw = (Decimal) quantity * unitPrice * (1 - discount);
        Decimal lineTotal = (Decimal) (Math.round((Double)(raw * 100)) / 100);

        Line line = new Line();
        line.sku = sku;
        line.quantity = quantity;
        line.unitPrice = unitPrice;
        line.discount = discount;
        line.lineTotal = lineTotal;

        return line;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines.size());
        ack.put('total', order.total);
        return JSON.serialize(ack);
    }
}
