public class LogPurgeJob implements Schedulable {

    public void execute(SchedulableContext SC) {
        Datetime thirtyDaysAgo = Datetime.now().addDays(-30);
        Datetime oneEightyDaysAgo = Datetime.now().addDays(-180);

        Integer batchSize = 5000;

        while (true) {
            List<FB_Integration_Log__c> logsToPurge = [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (
                    (CreatedDate < :thirtyDaysAgo AND (Level__c != 'ERROR' OR Level__c = NULL))
                    OR
                    (CreatedDate < :oneEightyDaysAgo AND Level__c = 'ERROR')
                )
                LIMIT :batchSize
            ];

            if (logsToPurge.isEmpty()) {
                break;
            }

            delete logsToPurge;
        }
    }

    public static Id scheduleNightly() {
        String cron = '0 2 * * *';
        return System.schedule('Log purge (nightly)', cron, new LogPurgeJob());
    }
}
