public class OpportunityRollupService {

    /**
     * Returns the closed-won revenue for the current calendar year for each requested account.
     * Every requested account Id is a key; accounts with no qualifying opportunities map to 0.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<Id, Decimal>();
        }

        // Seed the result so every requested account has a key with value 0
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        for (Id accountId : accountIds) {
            result.put(accountId, 0);
        }

        Integer currentYear = DateTime.now().year();
        Date startOfYear = Date.newInstance(currentYear, 1, 1);
        Date startOfNextYear = Date.newInstance(currentYear + 1, 1, 1);

        // Single aggregate query – respects the running user's sharing
        List<AggregateResult> rows = [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE IsWon = true
              AND CloseDate >= :startOfYear
              AND CloseDate < :startOfNextYear
              AND AccountId IN :accountIds
            GROUP BY AccountId
        ];

        // Overwrite only for accounts that actually have qualifying opportunities
        for (AggregateResult ar : rows) {
            Id accountId = (Id) ar.get('AccountId');
            if (accountId != null && result.containsKey(accountId)) {
                Decimal amount = (Decimal) ar.get('totalAmount');
                result.put(accountId, amount != null ? amount : 0);
            }
        }

        return result;
    }
}
