public class Opportunities extends fflib_SObjectDomain {

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        private final Opportunities domain;

        public Constructor() {
            domain = new Opportunities();
        }

        public fflib_SObjectDomain build() {
            return domain;
        }
    }

    public override void preValidate() {
        if (Trigger.isInsert) {
            validateAmountNotNegative(Trigger.new);
        }
        else if (Trigger.isUpdate) {
            validateAmountNotNegative(Trigger.new);
            validateWonAmountUnchanged(Trigger.new, Trigger.oldMap);
        }
    }

    private void validateAmountNotNegative(List<SObject> records) {
        for (SObject record : records) {
            Opportunity opp = (Opportunity) record;
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    private void validateWonAmountUnchanged(List<SObject> newRecords, Map<Id, SObject> oldMap) {
        for (SObject newRecord : newRecords) {
            Opportunity newOpp = (Opportunity) newRecord;
            Opportunity oldOpp = (Opportunity) oldMap.get(newOpp.Id);
            if (oldOpp.StageName == 'Closed Won' && newOpp.Amount != oldOpp.Amount) {
                error('Amount cannot change on a won opportunity.', newOpp, Opportunity.Amount);
            }
        }
    }
}
