public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        Set<String> seen = new Set<String>();
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>();

        // Base fields required by the credit team
        List<Schema.SObjectField> baseFields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
        for (Schema.SObjectField f : baseFields) {
            String name = f.getDescribe().getName();
            if (!seen.contains(name)) {
                fields.add(f);
                seen.add(name);
            }
        }

        // Dynamically include all fields in the Credit_Review field set
        // (admins add fields here without code changes)
        Map<String, Schema.FieldSetMember> fieldSetFields =
            Account.SObjectType.getDescribe().getFieldSetMap().get('Credit_Review').getDisplayedFields();
        for (String fieldName : fieldSetFields.keySet()) {
            if (!seen.contains(fieldName)) {
                fields.add(Account.SObjectType.getDescribe().fields.getMap().get(fieldName));
                seen.add(fieldName);
            }
        }

        return fields;
    }

    protected fflib_SObjectDataAccess getDataAccess() {
        return new fflib_SObjectDataAccess_UserMode();
    }

    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }
        String query = 'WITH USER_MODE SELECT ' + getFieldListString()
            + ' FROM Account WHERE Id IN :accountIds';
        return (List<Account>) getDataAccess().selectSObjects(query);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        // Build the Contacts subquery from ContactsSelector's field list
        ContactsSelector cs = new ContactsSelector();
        List<String> contactFieldNames = new List<String>();
        for (Schema.SObjectField f : cs.getSObjectFieldList()) {
            contactFieldNames.add(f.getDescribe().getName());
        }
        String subquery = 'SELECT ' + String.join(contactFieldNames, ', ') + ' FROM Contacts';

        String query = 'WITH USER_MODE SELECT ' + getFieldListString()
            + ' FROM Account WHERE Id IN :accountIds ' + subquery;

        return (List<Account>) getDataAccess().selectSObjects(query);
    }

    private String getFieldListString() {
        List<String> names = new List<String>();
        for (Schema.SObjectField f : getSObjectFieldList()) {
            names.add(f.getDescribe().getName());
        }
        return String.join(names, ', ');
    }

    /**
     * Data access that enforces WITH USER_MODE on every query it executes,
     * ensuring the platform applies the running user's object, field-level
     * security, and sharing rules.
     */
    private class fflib_SObjectDataAccess_UserMode extends fflib_SObjectDataAccess {

        public override List<SObject> selectSObjects(String queryString) {
            // Guard against double-prefixing if a caller already included a modifier
            if (!queryString.startsWith('WITH ')) {
                queryString = 'WITH USER_MODE ' + queryString;
            }
            return super.selectSObjects(queryString);
        }
    }
}
